import pandas as pd
import matplotlib.pyplot as plt
import io
import base64
import seaborn as sns

def get_base64_image(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', transparent=True, dpi=150)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Set aesthetic style
sns.set_theme(style="whitegrid")

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Preprocessing
df['Composer_List'] = df['Composer'].apply(lambda x: [c.strip() for c in str(x).split(',')])

# Exploded DataFrame for per-composer analysis
df_exploded = df.explode('Composer_List').rename(columns={'Composer_List': 'Individual_Composer'})

# KPIs
total_unique_composers = df_exploded['Individual_Composer'].nunique()
composer_counts = df_exploded['Individual_Composer'].value_counts()
max_wins_count = composer_counts.max()
max_wins_composers = composer_counts[composer_counts == max_wins_count].index.tolist()

# Repeat Winner Rate
seen = set()
repeat_ceremonies = 0
for idx, row in df.sort_values('Year').iterrows():
    comps = row['Composer_List']
    if any(c in seen for c in comps):
        repeat_ceremonies += 1
    for c in comps:
        seen.add(c)
repeat_winner_rate = (repeat_ceremonies / len(df)) * 100

# Decade with Most Unique Winners
df['Decade'] = (df['Year'] // 10) * 10
df_exploded['Decade'] = (df_exploded['Year'] // 10) * 10
decade_unique_counts = df_exploded.groupby('Decade')['Individual_Composer'].nunique()
max_unique_decade = decade_unique_counts.idxmax()

# Eras
def get_era(year):
    if year <= 1960: return 'Golden Age (1934-1960)'
    elif year <= 1980: return 'Silver Age (1961-1980)'
    elif year <= 2000: return 'Modern (1981-2000)'
    else: return 'Contemporary (2001-2026)'
df['Era'] = df['Year'].apply(get_era)
df_exploded['Era'] = df_exploded['Year'].apply(get_era)

# Longest Gap
gaps = []
for composer in composer_counts[composer_counts > 1].index:
    years = df_exploded[df_exploded['Individual_Composer'] == composer]['Year'].tolist()
    years.sort()
    for i in range(1, len(years)):
        gaps.append((years[i] - years[i-1], composer, years[i-1], years[i]))
gaps.sort(reverse=True)
longest_gap = gaps[0] if gaps else None

# Visualizations

# 1. Top Composers Chart
fig_top, ax_top = plt.subplots(figsize=(8, 5))
top_10 = composer_counts.head(10)
sns.barplot(x=top_10.values, y=top_10.index, ax=ax_top, palette="viridis")
ax_top.set_title("Most Awarded Composers", fontsize=14, weight='bold')
ax_top.set_xlabel("Number of Wins")
ax_top.set_ylabel("")
for i, v in enumerate(top_10.values):
    ax_top.text(v + 0.1, i, str(v), color='black', va='center', fontweight='bold')
img_top = get_base64_image(fig_top)
plt.close(fig_top)

# 2. Decade Distribution Chart
fig_dec, ax_dec = plt.subplots(figsize=(8, 4))
sns.barplot(x=decade_unique_counts.index.astype(str) + 's', y=decade_unique_counts.values, ax=ax_dec, palette="mako")
ax_dec.set_title("Unique Winners per Decade", fontsize=14, weight='bold')
ax_dec.set_xlabel("Decade")
ax_dec.set_ylabel("Unique Composers")
img_dec = get_base64_image(fig_dec)
plt.close(fig_dec)

# 3. Era Analysis Chart (Wins per Era)
fig_era, ax_era = plt.subplots(figsize=(8, 4))
era_counts = df['Era'].value_counts()
sns.barplot(y=era_counts.index, x=era_counts.values, ax=ax_era, palette="rocket")
ax_era.set_title("Total Wins per Era", fontsize=14, weight='bold')
ax_era.set_xlabel("Total Ceremonies")
ax_era.set_ylabel("")
img_era = get_base64_image(fig_era)
plt.close(fig_era)

